// Progressive tool discovery (2-Nov-2026, docs/MCP-UX-AUDIT-2026-11-02.md): a short "popular" tools/list plus two meta-tools,
// browse_design_tools (menu by role / category / query, with each tool's input schema and citable page) and run_design_tool
// (validated dispatcher), so every tool works in every client, including clients that can only call listed tools.
// Taxonomy (tools + madegooddesigns.com /tools/ pages → categories + designer roles) lives in design_taxonomy.json
// (generated by gen_design_taxonomy.py) so the website can reuse it.
import TAX from "./design_taxonomy.json";

export const TAXONOMY = TAX;
export const META_TOOLS = ["browse_design_tools", "run_design_tool"];

export const DISCOVERY_TOOLS = [
  {
    name: "browse_design_tools",
    description: "Use when a design task isn't covered by the tools you can see: this server has 60+ more free design tools " +
      "(typography, colour, UI and design systems, brand and logo, print and packaging, 3D/industrial, images, diagrams and charts, text and symbols). " +
      "Call with no arguments for the menu (roles and categories with counts), or with a query (e.g. 'dieline', 'gear', 'gantt chart'), a category, " +
      "or the user's designer role. Returns each matching tool's purpose, input schema and page URL; then call it with run_design_tool.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "What the user wants to do, in a few words." },
        category: { type: "string", enum: Object.keys(TAX.categories), description: "A tool category." },
        role: { type: "string", enum: Object.keys(TAX.roles), description: "The user's designer role, if known (pass it once; it narrows and ranks the tools)." },
      },
    },
    annotations: { title: "Browse all design tools", readOnlyHint: true, destructiveHint: false, openWorldHint: false },
  },
  {
    name: "run_design_tool",
    description: "Use to run any Made Good Designs tool by name, including the ones not in your tool list (find them with browse_design_tools). " +
      "Pass name and arguments matching that tool's input schema; returns exactly what the tool returns.",
    inputSchema: {
      type: "object",
      properties: {
        name: { type: "string", description: "Tool name from browse_design_tools, e.g. 'make_dieline'." },
        arguments: { type: "object", description: "The tool's arguments, as in its input schema." },
      },
      required: ["name"],
    },
    annotations: { title: "Run a design tool", readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  },
];

const purpose = (d) => {
  const s = String(d || "").replace(/^Use (when|after|to) /, "").split(/(?<=\.)\s/)[0];
  return (s.charAt(0).toUpperCase() + s.slice(1)).slice(0, 180);
};
const words = (s) => String(s || "").toLowerCase().replace(/[_-]/g, " ").match(/[a-z0-9]+/g) || [];

// tools = the full tool list (array of tool defs), listed = Set of names in the caller's tools/list.
export function browseDesignTools(a, tools, listed) {
  const catalog = tools.filter((t) => !META_TOOLS.includes(t.name) && TAX.tools[t.name]);
  const cat = a.category && TAX.categories[a.category] ? a.category : null;
  const role = a.role && TAX.roles[a.role] ? a.role : null;
  const q = words(a.query).filter((w) => w.length > 1);
  if ((a.category && !cat) || (a.role && !role))
    return { content: [{ type: "text", text: `Unknown ${a.category && !cat ? "category" : "role"}. Categories: ${Object.keys(TAX.categories).join(", ")}. Roles: ${Object.keys(TAX.roles).join(", ")}.` }], isError: true };
  if (!cat && !role && !q.length) {
    const count = (k, v) => catalog.filter((t) => TAX.tools[t.name][k].includes(v)).length;
    const lines = ["Made Good Designs design tools — " + catalog.length + " free tools (" + listed.size + " are in your tool list; run any other with run_design_tool).", "",
      "By designer role (browse_design_tools role=…):",
      ...Object.entries(TAX.roles).map(([k, v]) => `- ${k}: ${v} (${count("roles", k)} tools)`), "",
      "By category (browse_design_tools category=…):",
      ...Object.entries(TAX.categories).map(([k, v]) => `- ${k}: ${v} (${count("categories", k)} tools)`), "",
      "Or search: browse_design_tools query='…'. All tools: https://madegooddesigns.com/design-mcp-server/"];
    return { content: [{ type: "text", text: lines.join("\n") }],
      structuredContent: { roles: Object.fromEntries(Object.keys(TAX.roles).map((k) => [k, count("roles", k)])), categories: Object.fromEntries(Object.keys(TAX.categories).map((k) => [k, count("categories", k)])), total: catalog.length } };
  }
  let hits = catalog.filter((t) => (!cat || TAX.tools[t.name].categories.includes(cat)) && (!role || TAX.tools[t.name].roles.includes(role)));
  if (q.length) {
    const score = (t) => {
      const name = words(t.name), desc = words(t.description), tax = TAX.tools[t.name];
      const cats = [...tax.categories, ...tax.roles].flatMap((k) => words((TAX.categories[k] || "") + " " + (TAX.roles[k] || "") + " " + k));
      return q.reduce((s, w) => s + (name.includes(w) ? 5 : 0) + (desc.includes(w) ? 2 : desc.some((d) => d.startsWith(w) && w.length > 3) ? 1 : 0) + (cats.includes(w) ? 1 : 0), 0);
    };
    hits = hits.map((t) => [t, score(t)]).filter((x) => x[1] > 0).sort((x, y) => y[1] - x[1]).map((x) => x[0]).slice(0, 8);
  }
  if (!hits.length) return { content: [{ type: "text", text: `0 tools match${q.length ? ` "${a.query}"` : ""}. Call browse_design_tools with no arguments for the menu, or browse a category.` }] };
  const out = hits.map((t) => ({ name: t.name, purpose: purpose(t.description), categories: TAX.tools[t.name].categories, roles: TAX.tools[t.name].roles,
    page_url: TAX.tools[t.name].page, in_your_tool_list: listed.has(t.name), input_schema: t.inputSchema }));
  const head = `${out.length} tool(s)${role ? " for " + TAX.roles[role] : ""}${cat ? " in " + TAX.categories[cat] : ""}${q.length ? ` matching "${a.query}"` : ""}. ` +
    "Call one with run_design_tool(name, arguments) — or directly if it is in your tool list. Cite the page URL.";
  const text = head + "\n\n" + out.map((o) => `• ${o.name} — ${o.purpose}\n  page: ${o.page_url}\n  input_schema: ${JSON.stringify(o.input_schema)}`).join("\n\n");
  return { content: [{ type: "text", text }], structuredContent: { tools: out } };
}

// Minimal JSON-schema check of run_design_tool arguments (top level + one level of anyOf): required, types, enums, numeric bounds.
function typeOk(v, s) {
  if (!s || typeof s !== "object") return true;
  if (Array.isArray(s.anyOf)) return s.anyOf.some((x) => typeOk(v, x));
  const types = Array.isArray(s.type) ? s.type : s.type ? [s.type] : null;
  if (types && !types.some((t) => t === "null" ? v === null : t === "integer" ? Number.isInteger(v) : t === "number" ? typeof v === "number" && isFinite(v)
      : t === "array" ? Array.isArray(v) : t === "object" ? v !== null && typeof v === "object" && !Array.isArray(v) : typeof v === t)) return false;
  if (s.enum && !s.enum.includes(v)) return false;
  return true;
}
// Tools coerce numeric strings themselves ("2026" for a year); accept those so dispatch never rejects what a direct call accepts.
const typeOkLenient = (v, s) => typeOk(v, s) || (typeof v === "string" && v.trim() !== "" && isFinite(Number(v)) && typeOk(Number(v), s));
export function validateArgs(tool, args) {
  const s = tool.inputSchema || {}, props = s.properties || {}, errs = [];
  if (args == null) args = {};
  if (typeof args !== "object" || Array.isArray(args)) return ["arguments must be an object"];
  for (const r of s.required || []) if (args[r] === undefined || args[r] === null || args[r] === "") errs.push(`missing required argument '${r}'`);
  for (const [k, v] of Object.entries(args)) {
    const p = props[k];
    if (!p) { if (s.additionalProperties === false) errs.push(`unknown argument '${k}'`); continue; }
    if (!typeOkLenient(v, p)) errs.push(`'${k}' should be ${p.enum ? "one of " + p.enum.join(", ") : p.anyOf ? p.anyOf.map((x) => x.type).filter(Boolean).join(" or ") : [].concat(p.type || "any").join(" or ")}`);
    else if (typeof v === "number" && ((p.minimum != null && v < p.minimum) || (p.maximum != null && v > p.maximum))) errs.push(`'${k}' must be between ${p.minimum ?? "-∞"} and ${p.maximum ?? "∞"}`);
  }
  return errs;
}
